// playability probe: greedy over 60 turns win?
function play(seed){
  const G=newGame(seed);
  for(let t=0;t<200;t++){ if(G.over||G.people.length<=0)break; greedyStep(G); resolveTurn(G); if(G.pending)resolveChoice(G,0); }
  return {seed,over:G.over,turn:G.turn,pop:G.people.length,mor:Math.round(avgMorale(G)),tech:G.tech.length,score:(G.score||scoreOf(G)).total,sf:G.shortFood,sw:G.shortWater};
}
for(const sd of [1337,7,42,2024,99]) console.log(JSON.stringify(play(sd)));
